// Company career boards for the website, fetched through the same provider
// modules the CLI scanner uses. Static imports on purpose: Vercel bundles a
// function from what it imports, so the scanner's directory-wide dynamic
// loader would ship nothing. The board list is api/_lib/companies.json,
// generated by scripts/build-web-companies.mjs.

import ashby from '../../providers/ashby.mjs';
import greenhouse from '../../providers/greenhouse.mjs';
import lever from '../../providers/lever.mjs';
import workable from '../../providers/workable.mjs';
import { fetchJson, fetchText, fetchResponse, sleep } from '../../providers/_http.mjs';
import BOARDS from './companies.json' with { type: 'json' };

const PROVIDERS = { ashby, greenhouse, lever, workable };
const ctx = { transport: 'http', fetchJson, fetchText, fetchResponse, sleep };

export { BOARDS };

const isoDay = (ms) => (Number.isFinite(ms) && ms > 0 ? new Date(ms).toISOString().slice(0, 10) : null);

// Per-instance memory of each board's last fetch, so a detail request right
// after a listing does not download the whole board again.
const memo = new Map();
const TTL = 15 * 60 * 1000;

export async function fetchBoard(board) {
  const hit = memo.get(board.slug);
  if (hit && Date.now() - hit.at < TTL) return hit.jobs;
  const provider = PROVIDERS[board.provider];
  if (!provider) throw new Error(`no provider for ${board.slug}`);
  const entry = { name: board.name, careers_url: board.careers_url, api: board.api, provider: board.provider };
  const jobs = await provider.fetch(entry, ctx);
  memo.set(board.slug, { at: Date.now(), jobs });
  return jobs;
}

export function toListing(board, job) {
  return {
    key: `company:${board.slug}:${job.url}`,
    portal: 'company',
    board: board.slug,
    id: job.url,
    title: String(job.title || '').trim() || 'Untitled posting',
    company: job.company || board.name,
    location: job.location || null,
    date: isoDay(job.postedAt),
    deadline: null,
    url: job.url,
    applyUrl: null,
    snippet: null,
    tags: [board.provider],
    workMode: null,
  };
}

// Runs fn over items with at most `limit` in flight.
export async function pool(items, limit, fn) {
  const out = new Array(items.length);
  let next = 0;
  const workers = Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (next < items.length) {
      const i = next++;
      try { out[i] = { ok: true, value: await fn(items[i]) }; }
      catch (e) { out[i] = { ok: false, error: e instanceof Error ? e.message : String(e) }; }
    }
  });
  await Promise.all(workers);
  return out;
}
